import json, os, shutil, subprocess, sys
BIN="/workspace/executable"
BASE="/tmp/explore/collection-discovery/t"
def mk(name, files, dirs=(), links=()):
    d=os.path.join(BASE,name)
    if os.path.exists(d): shutil.rmtree(d)
    os.makedirs(d)
    for sub in dirs: os.makedirs(os.path.join(d,sub), exist_ok=True)
    for p,c in files.items():
        fp=os.path.join(d,p)
        os.makedirs(os.path.dirname(fp), exist_ok=True)
        with open(fp,'w') as f: f.write(c)
    for src,dst in links:
        os.symlink(src, os.path.join(d,dst))
    return d
def run(d, *args, cmd="export"):
    r=subprocess.run([BIN,cmd,*args,d], capture_output=True, text=True)
    return r
def ex(d, quiet=False):
    r=run(d)
    out={"exit":r.returncode,"stderr":r.stderr}
    try: out["j"]=json.loads(r.stdout)
    except Exception as e: out["raw"]=r.stdout
    return out
def summ(d, root=None):
    root = root or d
    o=ex(d)
    if "j" not in o:
        return f"EXIT={o['exit']} STDERR={o['stderr']!r} RAW={o.get('raw','')[:400]!r}"
    lines=[f"EXIT={o['exit']} stderr={o['stderr']!r} n={len(o['j']['cards'])}"]
    for c in o['j']['cards']:
        fp=c['location']['filePath']
        if fp.startswith(root+"/"): fp=fp[len(root)+1:]
        lines.append(f"  {c['hash'][:8]} deck={c['deckName']!r} file={fp!r} L{c['location']['lineStart']}-{c['location']['lineEnd']}")
    return "\n".join(lines)
EOF
